package com.newland.nsdk.core.api.external.display;

/**
 * Pre-defined messages in Chinese.
 */
public enum CNTextNotifyType {
    /**
     * Prompt message of transaction success.
     */
    TRANSACTION_SUCCESS,
    /**
     * Prompt message of transaction failed.
     */
    TRANSACTION_FAILED,
    /**
     * Prompt message of transaction timeout.
     */
    TRANSACTION_TIMEOUT,
    /**
     * Prompt message of transaction cancelled.
     */
    TRANSACTION_CANCELLED
}
